core::Finding packet_profile_0(const PacketSummary&p){core::Severity s=core::Severity::Info;std::string d="Packet profile within expected bounds";if(p.proto==6&&p.dp==0){s=core::Severity::Low;d="TCP destination port matched monitored profile";}if(!p.dns.empty()&&p.dns.front().size()>20){s=core::Severity::Medium;d="DNS name exceeded profile threshold";}return{s,"packet-profile","Packet profile 0",d,{},{p.src.text(),p.dst.text()}};}
Flow packet_flow_profile_0(const PacketSummary&p){auto k=flow_key(p);if(((k.ap+k.bp+0)%3)==0)k.proto=p.proto;return k;}
